'use strict';
// Disposable loopback fixture for manual/native file-dialog QA. No accounts.
const http=require('node:http'),fs=require('node:fs'),path=require('node:path');
const dir=path.resolve(process.argv[2]);fs.mkdirSync(dir,{recursive:true,mode:0o700});const requests=[];
const server=http.createServer((req,res)=>{requests.push(req.url);fs.writeFileSync(path.join(dir,'requests.json'),JSON.stringify(requests));res.setHeader('Content-Type','text/html; charset=utf-8');res.setHeader('Content-Security-Policy',"default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'");res.end('<!doctype html><title>Wiek portable storage fixture</title><style>body{font:20px system-ui;margin:50px;color:#27334b;background:#f4f6fa}pre{padding:24px;background:white;border-radius:12px}</style><h1 id="status">Storage fixture</h1><pre id="before"></pre><script>const tab=location.pathname===\"/two\"?\"two\":\"one\";window.beforeSiteScript={local:localStorage.getItem(\"shared\"),session:sessionStorage.getItem(\"tab\")};document.querySelector(\"#status\").textContent=beforeSiteScript.local&&beforeSiteScript.session?\"Restored before site script: \"+beforeSiteScript.session:\"Source tab: \"+tab;document.querySelector(\"#before\").textContent=JSON.stringify(beforeSiteScript,null,2);localStorage.setItem(\"shared\",\"native fixture local value\");sessionStorage.setItem(\"tab\",tab);</script>');});
server.listen(0,'127.0.0.1',()=>{const info={origin:'http://127.0.0.1:'+server.address().port,pid:process.pid};fs.writeFileSync(path.join(dir,'server.json'),JSON.stringify(info));console.log(JSON.stringify(info));});
process.on('SIGTERM',()=>server.close(()=>process.exit(0)));
